const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const ROOT = path.resolve(String($env.OPENCLAW_ASSET_SHARED_ROOT || '/data/openclaw-assets'));
const SLOT_DIR = path.join(ROOT, '_worker_slots');
const MAX_WORKER_SLOTS = 3;
const DEFAULT_LEASE_MS = 30 * 60 * 1000;
const usableStatuses = new Set(['accepted', 'accepted_fallback', 'accepted_fallback_unreviewed']);
const strictApprovedStatuses = new Set(['accepted']);
const terminalFailurePrefix = 'failed_';

fs.mkdirSync(SLOT_DIR, { recursive: true });

function readJson(filePath) {
  return JSON.parse(fs.readFileSync(filePath, 'utf8'));
}
function atomicJson(filePath, value) {
  const tmp = `${filePath}.${Date.now()}.${Math.random().toString(16).slice(2)}.tmp`;
  fs.writeFileSync(tmp, JSON.stringify(value, null, 2), 'utf8');
  fs.renameSync(tmp, filePath);
}
function sha256(filePath) {
  return `sha256:${crypto.createHash('sha256').update(fs.readFileSync(filePath)).digest('hex')}`;
}
function safeAssetId(value) {
  return String(value ?? 'asset').normalize('NFKC')
    .replace(/[^a-zA-Z0-9_-]+/g, '_').replace(/^_+|_+$/g, '') || 'asset';
}
function releaseSlot(slotPath, leaseId) {
  if (!slotPath || !fs.existsSync(slotPath)) return;
  try {
    const slot = readJson(slotPath);
    if (leaseId && slot.lease_id && slot.lease_id !== leaseId) return;
    fs.unlinkSync(slotPath);
  } catch {}
}
function reclaimExpiredSlots(now) {
  for (let slotId = 1; slotId <= MAX_WORKER_SLOTS; slotId += 1) {
    const slotPath = path.join(SLOT_DIR, `slot-${slotId}.json`);
    if (!fs.existsSync(slotPath)) continue;
    try {
      const slot = readJson(slotPath);
      const expiresAt = Date.parse(String(slot.expires_at ?? ''));
      if (Number.isFinite(expiresAt) && expiresAt > now) continue;
      fs.renameSync(slotPath, path.join(SLOT_DIR, `expired-slot-${slotId}-${Date.now()}-${Math.random().toString(16).slice(2)}.json`));
    } catch {}
  }
}
function acquireSlot(now) {
  reclaimExpiredSlots(now);
  for (let slotId = 1; slotId <= MAX_WORKER_SLOTS; slotId += 1) {
    const slotPath = path.join(SLOT_DIR, `slot-${slotId}.json`);
    const leaseId = typeof crypto.randomUUID === 'function' ? crypto.randomUUID() : crypto.randomBytes(16).toString('hex');
    const record = {
      schema_version: '3.0', slot_id: slotId, lease_id: leaseId, state: 'reserved',
      acquired_at: new Date(now).toISOString(),
      expires_at: new Date(now + DEFAULT_LEASE_MS).toISOString()
    };
    let fd;
    try {
      fd = fs.openSync(slotPath, 'wx', 0o600);
      fs.writeFileSync(fd, JSON.stringify(record, null, 2), 'utf8');
      fs.closeSync(fd);
      return { slotId, slotPath, leaseId, expiresAt: record.expires_at };
    } catch {
      if (fd !== undefined) try { fs.closeSync(fd); } catch {}
    }
  }
  return null;
}
function listJobDirs() {
  if (!fs.existsSync(ROOT)) return [];
  const jobs = [];
  for (const project of fs.readdirSync(ROOT, { withFileTypes: true })) {
    if (!project.isDirectory() || project.name.startsWith('_')) continue;
    const projectDir = path.join(ROOT, project.name);
    for (const job of fs.readdirSync(projectDir, { withFileTypes: true })) {
      if (!job.isDirectory()) continue;
      const jobDir = path.join(projectDir, job.name);
      if (fs.existsSync(path.join(jobDir, 'job.json'))) jobs.push(jobDir);
    }
  }
  return jobs;
}
function reusableStatus(jobDir, assetId, expectedFilename) {
  const statusPath = path.join(jobDir, '_status', `${assetId}.json`);
  if (!fs.existsSync(statusPath)) return null;
  try {
    const record = readJson(statusPath);
    if (!usableStatuses.has(record.final_status)) return null;
    if (record.asset_id !== assetId || record.filename !== expectedFilename) return null;
    const imagePath = path.resolve(jobDir, expectedFilename);
    const safeRoot = path.resolve(jobDir) + path.sep;
    if (!imagePath.startsWith(safeRoot) || !fs.existsSync(imagePath)) return null;
    const stat = fs.statSync(imagePath);
    if (!stat.isFile() || stat.size <= 0) return null;
    const hash = sha256(imagePath);
    if (record.sha256 && record.sha256 !== hash && `sha256:${record.sha256}` !== hash) return null;
    return { ...record, path: imagePath, file_size: stat.size, sha256: hash };
  } catch {
    return null;
  }
}
function archiveCollision(jobDir, runningPath, task, reason) {
  const logsDir = path.join(jobDir, '_logs');
  fs.mkdirSync(logsDir, { recursive: true });
  const assetId = safeAssetId(task.asset_id);
  const archivedPath = path.join(logsDir, `orphan_${assetId}_${Date.now()}_${Math.random().toString(16).slice(2)}.json`);
  task.orphan_archive_reason = reason;
  task.orphan_archived_at = new Date().toISOString();
  atomicJson(runningPath, task);
  fs.renameSync(runningPath, archivedPath);
}
function validateReferencePath(rawPath) {
  const resolved = path.resolve(String(rawPath ?? '').trim());
  const safeRoot = path.resolve(ROOT) + path.sep;
  if (!resolved.startsWith(safeRoot)) throw new Error(`参考图超出固定资产根目录：${resolved}`);
  if (!fs.existsSync(resolved) || !fs.statSync(resolved).isFile()) throw new Error(`参考图不存在：${resolved}`);
  const extension = path.extname(resolved).toLowerCase();
  if (!['.png', '.jpg', '.jpeg', '.webp'].includes(extension)) throw new Error(`参考图格式不支持：${extension}`);
  return resolved;
}
function readProjectRegistry(jobDir) {
  const registryPath = path.join(path.dirname(jobDir), 'reference_registry.json');
  if (!fs.existsSync(registryPath)) return { registryPath, assets: {} };
  try {
    const registry = readJson(registryPath);
    return { registryPath, assets: registry.assets ?? {} };
  } catch {
    return { registryPath, assets: {} };
  }
}
function resolveAssetRecord(jobDir, assetId, registryAssets) {
  const statusPath = path.join(jobDir, '_status', `${assetId}.json`);
  if (fs.existsSync(statusPath)) {
    try {
      const status = readJson(statusPath);
      if (usableStatuses.has(status.final_status)) {
        const imagePath = path.resolve(jobDir, status.filename);
        if (fs.existsSync(imagePath) && fs.statSync(imagePath).isFile() && fs.statSync(imagePath).size > 0) {
          return {
            asset_id: assetId,
            source: 'same_job_status',
            path: imagePath,
            final_status: status.final_status,
            registry_status: strictApprovedStatuses.has(status.final_status) ? 'approved' : 'provisional',
            reference_eligible: true,
            sha256: status.sha256 ?? null,
            record: status
          };
        }
      }
      if (String(status.final_status ?? '').startsWith(terminalFailurePrefix)) {
        return { asset_id: assetId, source: 'same_job_status', terminal_failure: true, final_status: status.final_status, record: status };
      }
    } catch {}
  }
  const registry = registryAssets[assetId];
  if (!registry) return null;
  const registryStatus = registry.status ?? registry.registry_status;
  if (['rejected', 'failed', 'superseded'].includes(registryStatus) || String(registry.final_status ?? '').startsWith(terminalFailurePrefix)) {
    return { asset_id: assetId, source: 'project_registry', terminal_failure: true, ...registry };
  }
  const candidatePath = String(registry.path ?? '').trim();
  if (!candidatePath || !fs.existsSync(candidatePath) || !fs.statSync(candidatePath).isFile()) return null;
  return { asset_id: assetId, source: 'project_registry', ...registry, path: candidatePath };
}
function writeDependencyState(jobDir, assetId, value) {
  const dir = path.join(jobDir, '_dependency_state');
  fs.mkdirSync(dir, { recursive: true });
  atomicJson(path.join(dir, `${assetId}.json`), {
    schema_version: '1.0', asset_id: assetId, checked_at: new Date().toISOString(), ...value
  });
}
function clearDependencyState(jobDir, assetId) {
  const statePath = path.join(jobDir, '_dependency_state', `${assetId}.json`);
  if (fs.existsSync(statePath)) fs.unlinkSync(statePath);
}
function resolveTaskReadiness(jobDir, task) {
  const { registryPath, assets: registryAssets } = readProjectRegistry(jobDir);
  const waiting = [];
  const failures = [];
  const dependencyRecords = [];
  for (const dependencyId of Array.isArray(task.depends_on) ? task.depends_on : []) {
    const record = resolveAssetRecord(jobDir, dependencyId, registryAssets);
    if (!record) {
      waiting.push({ type: 'dependency', asset_id: dependencyId, reason: 'not_completed' });
      continue;
    }
    if (record.terminal_failure) {
      failures.push({ type: 'dependency', asset_id: dependencyId, reason: record.final_status ?? 'failed' });
      continue;
    }
    dependencyRecords.push(record);
  }
  if (failures.length) return { state: 'failed', registry_path: registryPath, failures, waiting };

  const directPaths = [];
  const resolvedInputs = [];
  const omittedInputs = [];
  for (const rawPath of Array.isArray(task.reference_images) ? task.reference_images : []) {
    try {
      const resolved = validateReferencePath(rawPath);
      if (!directPaths.includes(resolved)) directPaths.push(resolved);
      resolvedInputs.push({ path: resolved, role: 'direct_reference', required: true, approved_only: false, source: 'direct_path' });
    } catch (error) {
      failures.push({ type: 'reference_path', path: rawPath, reason: error.message });
    }
  }

  const referenceInputs = Array.isArray(task.reference_inputs) ? task.reference_inputs : [];
  for (const input of referenceInputs) {
    if (input.path) {
      try {
        const resolved = validateReferencePath(input.path);
        if (!directPaths.includes(resolved)) directPaths.push(resolved);
        resolvedInputs.push({ ...input, path: resolved, source: 'direct_path' });
      } catch (error) {
        if (input.required !== false) failures.push({ type: 'reference_path', path: input.path, reason: error.message });
        else omittedInputs.push({ ...input, reason: error.message });
      }
      continue;
    }
    const record = resolveAssetRecord(jobDir, input.asset_id, registryAssets);
    if (!record) {
      if (input.required !== false) waiting.push({ type: 'reference_asset', asset_id: input.asset_id, reason: 'not_available' });
      else omittedInputs.push({ ...input, reason: 'not_available' });
      continue;
    }
    if (record.terminal_failure) {
      if (input.required !== false) failures.push({ type: 'reference_asset', asset_id: input.asset_id, reason: record.final_status ?? 'failed' });
      else omittedInputs.push({ ...input, reason: record.final_status ?? 'failed' });
      continue;
    }
    const approved = (record.status ?? record.registry_status) === 'approved' || strictApprovedStatuses.has(record.final_status);
    const allowProvisional = task.allow_provisional_references === true;
    if (input.approved_only !== false && !approved && !allowProvisional) {
      if (input.required !== false) waiting.push({ type: 'reference_asset', asset_id: input.asset_id, reason: 'not_approved' });
      else omittedInputs.push({ ...input, reason: 'not_approved' });
      continue;
    }
    const resolved = validateReferencePath(record.path);
    if (!directPaths.includes(resolved)) directPaths.push(resolved);
    resolvedInputs.push({
      ...input,
      path: resolved,
      source: record.source,
      source_status: record.registry_status ?? record.final_status ?? null,
      sha256: record.sha256 ?? null
    });
  }
  if (failures.length) return { state: 'failed', registry_path: registryPath, failures, waiting, resolved_reference_inputs: resolvedInputs };
  if (waiting.length) return { state: 'waiting', registry_path: registryPath, waiting, resolved_reference_inputs: resolvedInputs, omitted_reference_inputs: omittedInputs };

  const maximum = Math.max(1, Number(task.max_reference_images ?? 2));
  const sortedInputs = resolvedInputs.sort((a, b) => {
    const requiredA = a.required === false ? 1 : 0;
    const requiredB = b.required === false ? 1 : 0;
    return requiredA - requiredB || Number(a.priority ?? 999) - Number(b.priority ?? 999);
  });
  const requiredPaths = [...new Set(sortedInputs.filter((item) => item.required !== false).map((item) => item.path))];
  if (requiredPaths.length > maximum) {
    return {
      state: 'failed', registry_path: registryPath,
      failures: [{ type: 'reference_limit', reason: `必需参考图 ${requiredPaths.length} 张，超过当前上限 ${maximum} 张` }],
      resolved_reference_inputs: sortedInputs
    };
  }
  const selectedInputs = [];
  const selectedPaths = [];
  for (const input of sortedInputs) {
    if (selectedPaths.includes(input.path)) continue;
    if (selectedPaths.length >= maximum) {
      omittedInputs.push({ ...input, reason: 'maximum_reference_images_reached' });
      continue;
    }
    selectedPaths.push(input.path);
    selectedInputs.push(input);
  }
  return {
    state: 'ready', registry_path: registryPath,
    dependency_records: dependencyRecords,
    reference_images: selectedPaths,
    resolved_reference_inputs: selectedInputs,
    omitted_reference_inputs: omittedInputs
  };
}
function markDependencyFailure(jobDir, queuePath, task, readiness) {
  const statusDir = path.join(jobDir, '_status');
  const doneDir = path.join(jobDir, '_queue_done');
  fs.mkdirSync(statusDir, { recursive: true });
  fs.mkdirSync(doneDir, { recursive: true });
  const record = {
    schema_version: '3.0', project_id: task.project_id, job_id: task.job_id,
    asset_id: task.asset_id, category: task.category, name: task.name, filename: task.filename,
    payload_sha256: task.payload_sha256 ?? null, asset_role: task.asset_role ?? null, asset_kind: task.asset_kind ?? null,
    angle_id: task.angle_id ?? null, layout_type: task.layout_type ?? null,
    contains_multiple_independent_assets: task.contains_multiple_independent_assets === true,
    final_status: 'failed_dependency',
    final_reason: JSON.stringify(readiness.failures ?? []),
    depends_on: task.depends_on ?? [],
    reference_inputs: task.reference_inputs ?? [],
    failed_at: new Date().toISOString()
  };
  atomicJson(path.join(statusDir, `${task.asset_id}.json`), record);
  const donePath = path.join(doneDir, `${task.asset_id}.json`);
  if (fs.existsSync(donePath)) fs.unlinkSync(donePath);
  fs.renameSync(queuePath, donePath);
  writeDependencyState(jobDir, task.asset_id, { state: 'failed', failures: readiness.failures ?? [] });
}

const now = Date.now();
const workerSlot = acquireSlot(now);
if (!workerSlot) return [];

const jobs = listJobDirs();
const candidates = [];
for (const jobDir of jobs) {
  const queueDir = path.join(jobDir, '_queue');
  const runningDir = path.join(jobDir, '_running');
  const doneDir = path.join(jobDir, '_queue_done');
  fs.mkdirSync(queueDir, { recursive: true });
  fs.mkdirSync(runningDir, { recursive: true });
  fs.mkdirSync(doneDir, { recursive: true });

  for (const name of fs.readdirSync(runningDir).filter((item) => item.endsWith('.json'))) {
    const runningPath = path.join(runningDir, name);
    try {
      const staleTask = readJson(runningPath);
      const explicitExpiry = Date.parse(String(staleTask.lease_expires_at ?? ''));
      const fallbackExpiry = fs.statSync(runningPath).mtimeMs + DEFAULT_LEASE_MS;
      const expiresAt = Number.isFinite(explicitExpiry) ? explicitExpiry : fallbackExpiry;
      if (expiresAt > now) continue;
      releaseSlot(staleTask.worker_slot_path, staleTask.lease_id);
      const assetId = safeAssetId(staleTask.asset_id);
      const existing = reusableStatus(jobDir, staleTask.asset_id, staleTask.filename);
      if (existing) {
        staleTask.recovered_as_completed_at = new Date().toISOString();
        atomicJson(runningPath, staleTask);
        const donePath = path.join(doneDir, `${assetId}.json`);
        if (fs.existsSync(donePath)) archiveCollision(jobDir, runningPath, staleTask, '已有完成任务，归档过期租约');
        else fs.renameSync(runningPath, donePath);
      } else {
        const recovered = {
          ...staleTask, not_before: 0, recovered_from_stale_at: new Date().toISOString(),
          previous_lease_id: staleTask.lease_id ?? null, lease_id: null, lease_expires_at: null,
          running_task_path: null, worker_slot_id: null, worker_slot_path: null
        };
        atomicJson(runningPath, recovered);
        const queuePath = path.join(queueDir, `${assetId}.json`);
        if (fs.existsSync(queuePath)) archiveCollision(jobDir, runningPath, recovered, '队列中已有同资产任务，避免覆盖');
        else fs.renameSync(runningPath, queuePath);
      }
    } catch (error) {
      const logsDir = path.join(jobDir, '_logs');
      fs.mkdirSync(logsDir, { recursive: true });
      atomicJson(path.join(logsDir, `stale_recovery_${Date.now()}.json`), { file: runningPath, error: error.message, at: new Date().toISOString() });
    }
  }

  for (const name of fs.readdirSync(queueDir).filter((item) => item.endsWith('.json'))) {
    const queuePath = path.join(queueDir, name);
    try {
      const task = readJson(queuePath);
      if (Number(task.not_before ?? 0) > now) continue;
      const readiness = resolveTaskReadiness(jobDir, task);
      if (readiness.state === 'failed') {
        markDependencyFailure(jobDir, queuePath, task, readiness);
        continue;
      }
      if (readiness.state === 'waiting') {
        writeDependencyState(jobDir, task.asset_id, { state: 'waiting', waiting: readiness.waiting ?? [], registry_path: readiness.registry_path });
        continue;
      }
      clearDependencyState(jobDir, task.asset_id);
      const stagePriority = { anchor: 0, derived: 1, shot: 2 }[String(task.generation_stage ?? 'derived')] ?? 1;
      candidates.push({
        queuePath, jobDir, assetId: safeAssetId(task.asset_id),
        stagePriority, priority: Number(task.asset_index ?? 999999), queuedAt: String(task.queued_at ?? ''), readiness
      });
    } catch (error) {
      const logsDir = path.join(jobDir, '_logs');
      fs.mkdirSync(logsDir, { recursive: true });
      atomicJson(path.join(logsDir, `queue_scan_${Date.now()}_${Math.random().toString(16).slice(2)}.json`), { file: queuePath, error: error.message, at: new Date().toISOString() });
    }
  }
}

candidates.sort((a, b) => a.stagePriority - b.stagePriority || a.priority - b.priority || a.queuedAt.localeCompare(b.queuedAt));
for (const candidate of candidates) {
  const runningName = `${candidate.assetId}__${workerSlot.leaseId}.json`;
  const runningPath = path.join(candidate.jobDir, '_running', runningName);
  try { fs.renameSync(candidate.queuePath, runningPath); } catch { continue; }
  const task = readJson(runningPath);
  Object.assign(task, {
    output_dir: candidate.jobDir,
    reference_registry_path: candidate.readiness.registry_path,
    reference_images: candidate.readiness.reference_images ?? [],
    resolved_reference_inputs: candidate.readiness.resolved_reference_inputs ?? [],
    omitted_reference_inputs: candidate.readiness.omitted_reference_inputs ?? [],
    dependency_records: candidate.readiness.dependency_records ?? [],
    lease_id: workerSlot.leaseId,
    lease_expires_at: workerSlot.expiresAt,
    running_task_path: runningPath,
    worker_slot_id: workerSlot.slotId,
    worker_slot_path: workerSlot.slotPath,
    worker_execution_count: Number(task.worker_execution_count ?? 0) + 1,
    claimed_at: new Date().toISOString()
  });
  atomicJson(runningPath, task);
  atomicJson(workerSlot.slotPath, {
    schema_version: '3.0', slot_id: workerSlot.slotId, lease_id: workerSlot.leaseId, state: 'running',
    project_id: task.project_id, job_id: task.job_id, asset_id: task.asset_id,
    running_task_path: runningPath, acquired_at: task.claimed_at, expires_at: workerSlot.expiresAt
  });
  const existing = reusableStatus(candidate.jobDir, task.asset_id, task.filename);
  return [{ json: { ...task, skip_generation: Boolean(existing), existing_status: existing } }];
}
releaseSlot(workerSlot.slotPath, workerSlot.leaseId);
return [];

const item = $input.first().json;
  if (!item.output_dir) throw new Error('Worker 任务缺少 output_dir');
