  function updateOwnedFile(filePath, mutate, label) {
    const fd = fs.openSync(filePath, 'r+');
    try {
      const live = JSON.parse(fs.readFileSync(fd, 'utf8'));
      if (live.lease_id && source.lease_id && live.lease_id !== source.lease_id) {
        throw new Error(`${label}已被其他执行持有`);
      }
      const buffer = Buffer.from(JSON.stringify(mutate(live), null, 2), 'utf8');
      fs.ftruncateSync(fd, 0);
