    if (!fs.existsSync(filePath)) throw new Error(`${label}已在续租期间被回收`);
    const current = JSON.parse(fs.readFileSync(filePath, 'utf8'));
    if (current.lease_id && source.lease_id && current.lease_id !== source.lease_id) {
      throw new Error(`${label}已在续租期间被替换`);
    }
  }

  updateOwnedFile(
    slotPath,
    (slot) => ({ ...slot, state: 'reviewing', expires_at: expiresAt }),
    'Worker 槽位'
  );
  updateOwnedFile(
    runningPath,
