function buildDiagnostic() {
  return [
    promptBlockReason
      ? `prompt_block=${promptBlockReason}`
      : '',
    finishReason
      ? `finish_reason=${finishReason}`
      : 'finish_reason=NO_CANDIDATE_TEXT',
    finishMessage
      ? `finish_message=${finishMessage}`
      : '',
    usageMetadata.thoughtsTokenCount != null
      ? `thinking_tokens=${usageMetadata.thoughtsTokenCount}`
      : '',
    usageMetadata.candidatesTokenCount != null
      ? `candidate_tokens=${usageMetadata.candidatesTokenCount}`
      : ''
  ].filter(Boolean).join('；');
}

// 从原提示词中移除容易触发内容策略的叙事情节，
// 只保留中性的外观、服装、场景、构图和风格要求。
// 这里只用于“质检重试”，不会用于重新生图。
function buildNeutralVisualPrompt(value) {
  const source = String(value ?? '')
    .normalize('NFKC')
    .replace(/\r/g, '\n')
    .trim();

  if (!source) {
    return [
      '静态视觉资产质量检查。',
      '核对主体是否完整、结构是否自然、服装与颜色是否稳定、',
      '背景是否清晰、构图是否合理、画面是否存在明显生成缺陷。'
    ].join('');
  }

  const sensitivePattern =
    /(未成年|儿童|幼童|小孩|男孩|女孩|学生|校园欺凌|欺凌|暴力|打斗|殴打|攻击|受伤|伤势|伤口|流血|血液|鲜血|死亡|尸体|杀害|自残|虐待|武器|刀具|枪械|毒品|色情|裸露|性行为|minor|child|kid|boy|girl|student|school\s*bully|bully|violence|violent|fight|beating|assault|injury|injured|wound|blood|bleeding|death|dead\s*body|corpse|kill|self[-\s]?harm|abuse|weapon|knife|gun|drug|sexual|nude)/i;

  const segments = source
    .split(/[。！？!?；;\n]+/)
    .map((item) => item.trim())
    .filter(Boolean)
    .filter((item) => !sensitivePattern.test(item));

  const neutralDetails = segments
    .join('；')
    .replace(/\s+/g, ' ')
    .slice(0, 1800)
    .trim();

  return [
    '静态视觉资产质量检查。',
    '只核对图片中可以直接观察到的视觉属性：主体完整性、数量、',
    '外观轮廓、发型、服装、颜色、材质、姿态、道具、背景、',
    '空间关系、构图、画幅、灯光、风格以及明显生成缺陷。',
    '不要推断人物年龄、身份或故事情节；不要描述或评价敏感行为。',
    neutralDetails
      ? `中性视觉要求：${neutralDetails}`
      : '中性视觉要求：画面主体完整，结构自然，视觉设定稳定，背景和构图清晰。'
  ].join('\n');
}

function rememberOriginalFields(current) {
  if (current.review_original_fields) {
    return current.review_original_fields;
  }

  return {
    name: current.name,
    prompt_zh: current.prompt_zh,
    prompt_en: current.prompt_en,
    negative_prompt: current.negative_prompt
  };
}

function restoreOriginalFields(current) {
  const original = current.review_original_fields;

  if (!original || typeof original !== 'object') {
    return {
      ...current,
      review_safe_mode: false
    };
  }

  const {
    review_original_fields: _originalFields,
    ...rest
  } = current;

  return {
    ...rest,
    name: original.name,
    prompt_zh: original.prompt_zh,
    prompt_en: original.prompt_en,
    negative_prompt: original.negative_prompt,
    review_safe_mode: false
  };
}

// Gemini 有时返回 HTTP 200，但没有候选文本。
// 普通空响应继续走原有接口重试。
// PROHIBITED_CONTENT 第一次出现时，自动改用中性质检提示词重试一次。
if (!text) {
  const diagnostic =
    buildDiagnostic() ||
    '质检接口返回空内容';

  const maxApiRetries = Math.max(
    1,
    Number(asset.review_api_max_retries ?? 8)
  );

  if (isProhibitedContent && !isSafeFallback) {
    const originalFields =
      rememberOriginalFields(asset);

    const neutralSource = [
      asset.prompt_zh,
      asset.prompt_en
    ].filter(Boolean).join('\n');

    return [{
      json: {
        ...asset,

        // 暂存原字段，质检完成后恢复，防止影响后续生图。
        review_original_fields: originalFields,

