        name: `视觉资产 ${asset.asset_id || asset.asset_index || ''}`.trim(),
        prompt_zh: buildNeutralVisualPrompt(neutralSource),
        prompt_en: '',
        negative_prompt: '',

        review_safe_mode: true,
        review_safe_fallback_attempted: true,
        review_response_ok: false,
        review_pass: false,

        // 保证能进入现有“质检接口是否继续重试”真分支。
        review_api_retry_count: Math.min(
          Number(asset.review_api_retry_count ?? 0) + 1,
          Math.max(0, maxApiRetries - 1)
        ),

        review_api_error:
          `${diagnostic}；已切换为中性视觉质检，下一次请求不再原样发送敏感叙事文本`,

        review_finish_reason:
          finishReason || null,
        review_finish_message:
          finishMessage || null,
        review_prompt_block_reason:
          promptBlockReason || null,
        review_safety_ratings:
          safetyRatings,
        review_usage_metadata:
          usageMetadata
      }
    }];
  }

  // 中性降级请求仍被内容策略拦截时立即终止，
  // 将重试次数设为上限，避免重复发送同一请求。
  if (isProhibitedContent && isSafeFallback) {
    const restoredAsset =
      restoreOriginalFields(asset);

    return [{
      json: {
        ...restoredAsset,
        review_response_ok: false,
