        review_finish_reason:
          finishReason || null,
        review_finish_message:
          finishMessage || null,
        review_prompt_block_reason:
          promptBlockReason || null,
        review_safety_ratings:
          safetyRatings,
        review_usage_metadata:
          usageMetadata
      }
    }];
  }

  // 不是内容策略拦截：按原逻辑处理普通空响应或临时接口异常。
  const apiRetryCount =
    Number(asset.review_api_retry_count ?? 0) + 1;

  return [{
    json: {
      ...asset,
      review_response_ok: false,
      review_pass: false,
      review_api_retry_count: apiRetryCount,
      review_api_error: diagnostic,
      review_finish_reason:
        finishReason || null,
      review_finish_message:
        finishMessage || null,
      review_prompt_block_reason:
        promptBlockReason || null,
      review_safety_ratings:
        safetyRatings,
      review_usage_metadata:
        usageMetadata
    }
