text = text
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let result;

try {
  result = JSON.parse(text);
} catch (error) {
  const match = text.match(/\{[\s\S]*\}/);

  if (!match) {
    const apiRetryCount =
      Number(asset.review_api_retry_count ?? 0) + 1;

    return [{
      json: {
        ...asset,
        review_response_ok: false,
        review_pass: false,
        review_api_retry_count: apiRetryCount,
        review_api_error:
          `质检结果不是有效 JSON：${text.slice(0, 500)}`,
        review_finish_reason:
          finishReason || null,
        review_finish_message:
          finishMessage || null,
        review_prompt_block_reason:
          promptBlockReason || null,
        review_safety_ratings:
          safetyRatings,
        review_usage_metadata:
          usageMetadata
      }
    }];
  }

  try {
    result = JSON.parse(match[0]);
  } catch (nestedError) {
    const apiRetryCount =
      Number(asset.review_api_retry_count ?? 0) + 1;

    return [{
      json: {
        ...asset,
        review_response_ok: false,
        review_pass: false,
        review_api_retry_count: apiRetryCount,
        review_api_error:
          `提取到 JSON 外形，但解析失败：${match[0].slice(0, 500)}`,
        review_finish_reason:
          finishReason || null,
        review_finish_message:
          finishMessage || null,
        review_prompt_block_reason:
          promptBlockReason || null,
        review_safety_ratings:
          safetyRatings,
        review_usage_metadata:
          usageMetadata
      }
    }];
  }
}

// 如果本次使用的是中性降级质检，先恢复原始提示词。
// 这样质检不通过后重新生图时，仍使用原始资产提示词。
const restoredAsset =
  restoreOriginalFields(asset);

const positiveRequirements =
  Array.isArray(result.positive_requirements)
    ? result.positive_requirements
    : [];

const negativeRequirements =
  Array.isArray(result.negative_requirements)
    ? result.negative_requirements
    : [];

const modelHardFailures =
  Array.isArray(result.hard_requirement_failures)
    ? result.hard_requirement_failures
        .map(String)
        .filter(Boolean)
    : [];

const derivedPositiveHardFailures =
  positiveRequirements
    .filter((item) =>
      String(item?.priority || '').toLowerCase() === 'hard' &&
      item?.matched !== true
    )
    .map((item) =>
      String(
        item?.requirement ||
        item?.source_text ||
        '未满足的硬性正向要求'
      )
    );

const violatedNegativeRequirements =
  negativeRequirements
    .filter((item) =>
      item?.violated === true
    )
    .map((item) =>
      String(
        item?.requirement ||
        item?.source_text ||
        '违反负向提示词'
      )
    );

const productionSafety =
  result.production_safety &&
  typeof result.production_safety === 'object' &&
  !Array.isArray(result.production_safety)
    ? result.production_safety
    : {};
const category = String(restoredAsset.category ?? '').toLowerCase();
const hasReferenceImages =
  (Array.isArray(restoredAsset.reference_images) && restoredAsset.reference_images.length > 0) ||
  (Array.isArray(restoredAsset.resolved_reference_inputs) && restoredAsset.resolved_reference_inputs.length > 0);
const identityConsistencyExpected =
  hasReferenceImages && /^(character|animal|creature)$/.test(category);
const sceneTopologyExpected =
  hasReferenceImages && /^(location|scene|shot|storyboard|environment)$/.test(category);
const videoReferenceExpected =
  String(restoredAsset.asset_role ?? '') === 'video_reference';
const safetyFailures = [];

if (Object.keys(productionSafety).length === 0) {
  safetyFailures.push('缺少 production_safety 结构化生产安全证据');
}
if (hasReferenceImages && productionSafety.reference_consistency_checked !== true) {
  safetyFailures.push('存在参考图但未完成参考一致性检查');
}
if (identityConsistencyExpected && (
  productionSafety.identity_consistency_applicable !== true ||
  productionSafety.identity_consistent !== true
)) {
  safetyFailures.push('人物/生物参考身份连续性未明确通过');
}
if (sceneTopologyExpected && (
  productionSafety.scene_topology_applicable !== true ||
  productionSafety.scene_topology_consistent !== true
)) {
  safetyFailures.push('场景参考拓扑连续性未明确通过');
}
if (videoReferenceExpected && productionSafety.single_view_clean !== true) {
  safetyFailures.push('视频参考图不是干净单视图');
}
if (videoReferenceExpected && productionSafety.contains_multiple_independent_assets !== false) {
  safetyFailures.push('视频参考图包含多个独立资产或状态未知');
}
if (videoReferenceExpected && productionSafety.contains_text_or_annotations !== false) {
  safetyFailures.push('视频参考图包含文字/标注或状态未知');
}

const hardFailures = [
  ...new Set([
    ...modelHardFailures,
    ...derivedPositiveHardFailures,
    ...violatedNegativeRequirements,
    ...safetyFailures
  ])
];

const rawScore = Number(result.score ?? 0);

const score = Math.min(
  100,
  Math.max(
    0,
    Number.isFinite(rawScore)
      ? rawScore
      : 0
  )
);

const modelPass = Boolean(result.pass);

const reviewPass =
  modelPass &&
  score >= Number(restoredAsset.review_min_score ?? 80) &&
  hardFailures.length === 0;

const positiveFixes =
  positiveRequirements
    .filter((item) =>
      item?.matched !== true
    )
    .map((item) =>
      String(item?.fix_instruction || '').trim()
    )
    .filter(Boolean);

const negativeFixes =
  negativeRequirements
    .filter((item) =>
      item?.violated === true
    )
    .map((item) =>
      String(item?.fix_instruction || '').trim()
    )
    .filter(Boolean);

const modelFixPrompt =
  String(result.fix_prompt ?? '').trim();

const reason =
  String(result.reason ?? '').trim();

const feedbackParts = [
  modelFixPrompt,
  ...positiveFixes,
  ...negativeFixes,
  hardFailures.length
    ? `必须满足或修正：${hardFailures.join('；')}`
    : ''
].filter(Boolean);

const history =
  Array.isArray(restoredAsset.review_history)
    ? [...restoredAsset.review_history]
    : [];

history.push({
  attempt:
    Number(restoredAsset.review_retry_count ?? 0) + 1,
  mode: isSafeFallback
    ? 'safe_visual_fallback'
    : 'full_prompt_review',
  pass: reviewPass,
  score,
  reason: reason.slice(0, 500),
  hard_requirement_failures:
    hardFailures.slice(0, 20),
  production_safety: productionSafety,
  review_provider: normalizedProvider,
  review_model: normalizedModel,
  reviewed_at:
    new Date().toISOString()
});

return [{
  json: {
    ...restoredAsset,

    review_response_ok: true,
    review_provider_used: normalizedProvider,
    review_model_used: normalizedModel,
    review_api_retry_count: 0,
    review_api_error: null,

    review_pass: reviewPass,
    review_model_pass: modelPass,
    review_score: score,
    review_reason: reason,

    review_mode: isSafeFallback
      ? 'safe_visual_fallback'
      : 'full_prompt_review',

    review_safe_fallback_used:
      isSafeFallback,

    review_prompt_summary:
      String(result.prompt_summary ?? ''),

    review_positive_requirements:
      positiveRequirements,

    review_negative_requirements:
      negativeRequirements,

    review_hard_requirement_failures:
      hardFailures,

    review_production_safety: {
      ...productionSafety,
      ambiguity_reasons: Array.isArray(productionSafety.ambiguity_reasons)
        ? productionSafety.ambiguity_reasons.map(String).filter(Boolean).slice(0, 20)
        : [],
      reference_image_count: Array.isArray(restoredAsset.resolved_reference_inputs)
        ? restoredAsset.resolved_reference_inputs.length
        : 0
    },

    qa_feedback:
      [...new Set(feedbackParts)].join('；'),

    review_history:
      history.slice(-5),

    review_finish_reason:
      finishReason || null,

    review_prompt_block_reason: null,
    review_prompt_blocked_terminal: false,
    review_usage_metadata:
      usageMetadata
  }
}];

return [{
  json: {
    ...$json,
    review_retry_count: Number($json.review_retry_count ?? 0) + 1
  }
}];

