    name: source?.name ?? own.name ?? null,
    message: String(message),
    code: code === null ? null : String(code),
    status,
    statusCode: status,
    response: response ? {
      status: response.status ?? null,
      statusText: response.statusText ?? null,
      data: scalar(data),
    } : null,
    own_properties: own,
  };
  item.json.provider_transport_error_captured = true;
}

return items;
